CREATE EXTENSION IF NOT EXISTS vector;

CREATE TABLE chunks (
  id           bigserial PRIMARY KEY,
  tenant_id    bigint    NOT NULL,          -- чей это документ
  doc_id       text      NOT NULL,
  doc_version  int       NOT NULL,
  chunk_index  int       NOT NULL,          -- номер куска внутри версии
  section      text,                        -- раздел: для фильтров и для цитат
  content      text      NOT NULL,
  embedding    vector(3) NOT NULL,          -- в проде 1024 или сколько выдаёт твоя модель
  created_at   timestamptz NOT NULL DEFAULT now(),
  UNIQUE (doc_id, doc_version, chunk_index) -- повторная загрузка не создаст дублей
);
CREATE INDEX ON chunks USING hnsw (embedding vector_cosine_ops);
CREATE INDEX ON chunks (tenant_id);

-- версия 2 документа: вставить новые куски и удалить старые, атомарно
BEGIN;
INSERT INTO chunks (tenant_id, doc_id, doc_version, chunk_index, content, embedding) VALUES
  (42, 'refund-policy', 2, 0, 'Возврат в течение 14 дней.',    '[0.9,0.2,0.0]'),
  (42, 'refund-policy', 2, 1, 'Деньги возвращаются на карту.', '[0.2,0.8,0.1]')
ON CONFLICT (doc_id, doc_version, chunk_index)
  DO UPDATE SET content = EXCLUDED.content, embedding = EXCLUDED.embedding;
DELETE FROM chunks WHERE doc_id = 'refund-policy' AND doc_version < 2;
COMMIT;

// Два ранжированных списка id кусков, лучший первым
const vectorHits = ["c4", "c9", "c2", "c7"]; // pgvector: ближе всего по смыслу
const bm25Hits = ["c7", "c4", "c5"];         // BM25: точные слова, например "TS-999"

// Reciprocal Rank Fusion: score(d) = сумма по спискам 1 / (k + место d)
function rrf(lists, k = 60) {
  const score = new Map();
  for (const list of lists)
    list.forEach((id, i) => score.set(id, (score.get(id) ?? 0) + 1 / (k + i + 1)));
  return [...score].sort((a, b) => b[1] - a[1]).map(([id, s]) => id + " " + s.toFixed(4));
}
console.log(rrf([vectorHits, bm25Hits]));
// [ 'c4 0.0325', 'c7 0.0320', 'c9 0.0161', 'c2 0.0159', 'c5 0.0159' ]

// chunks[i] показан модели как [i + 1]
const chunks = [
  "Возврат товара возможен в течение 14 дней.",
  "Уценённый товар возврату не подлежит, если дефект указан в чеке.",
];
const answer =
  "Вернуть товар можно в течение 14 дней [1]. Доставка бесплатная [3]. " +
  "Уценённый товар с указанным дефектом не вернуть [2]. Деньги придут за 3 дня.";

function verifyCitations(answer, n) {
  const kept = [], dropped = [];
  for (const s of answer.split(/(?<=[.!?])\s+/)) {
    const refs = [...s.matchAll(/\[(\d+)\]/g)].map((m) => Number(m[1]));
    const ok = refs.length > 0 && refs.every((r) => r >= 1 && r <= n);
    (ok ? kept : dropped).push(s);
  }
  return { kept: kept.join(" "), dropped };
}
console.log(verifyCitations(answer, chunks.length));
// { kept: 'Вернуть товар можно в течение 14 дней [1]. Уценённый товар с указанным дефектом не вернуть [2].',
//   dropped: [ 'Доставка бесплатная [3].', 'Деньги придут за 3 дня.' ] }

-- 1. Дочитывать индекс, пока LIMIT не наберётся (pgvector 0.8.0+)
SET hnsw.iterative_scan = strict_order;

-- 2. Несколько крупных тенантов: частичный индекс на каждого
CREATE INDEX ON chunks USING hnsw (embedding vector_cosine_ops) WHERE (tenant_id = 42);

-- 3. Много тенантов: партиция на тенанта, у каждой свой маленький индекс
CREATE TABLE chunks (tenant_id bigint NOT NULL, embedding vector(1024) /* ... */)
  PARTITION BY LIST (tenant_id);

ALTER TABLE chunks ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON chunks
  USING (tenant_id = current_setting('app.tenant_id', true)::bigint);

-- приложение ходит в базу ролью app, не владельцем таблицы
SET ROLE app;
SELECT count(*) FROM chunks;              -- 0: тенант не задан, не видно ничего

BEGIN;
SET LOCAL app.tenant_id = '42';           -- на время одной транзакции
SELECT content FROM chunks ORDER BY embedding <=> '[1,0.1,0]' LIMIT 20;
-- Возврат в течение 14 дней.
-- Деньги возвращаются на карту.         (кусок тенанта 7 не виден)
COMMIT;

RESET ROLE;                               -- владелец таблицы
SELECT count(*) FROM chunks;              -- 3: владелец обходит RLS

CREATE EXTENSION IF NOT EXISTS vector;

CREATE TABLE chunks (
  id           bigserial PRIMARY KEY,
  tenant_id    bigint    NOT NULL,          -- whose document this is
  doc_id       text      NOT NULL,
  doc_version  int       NOT NULL,
  chunk_index  int       NOT NULL,          -- chunk number within the version
  section      text,                        -- section: for filters and citations
  content      text      NOT NULL,
  embedding    vector(3) NOT NULL,          -- 1024 in production, or whatever your model outputs
  created_at   timestamptz NOT NULL DEFAULT now(),
  UNIQUE (doc_id, doc_version, chunk_index) -- re-uploading cannot create duplicates
);
CREATE INDEX ON chunks USING hnsw (embedding vector_cosine_ops);
CREATE INDEX ON chunks (tenant_id);

-- version 2 of the document: insert the new chunks and delete the old ones, atomically
BEGIN;
INSERT INTO chunks (tenant_id, doc_id, doc_version, chunk_index, content, embedding) VALUES
  (42, 'refund-policy', 2, 0, 'Returns accepted within 14 days.', '[0.9,0.2,0.0]'),
  (42, 'refund-policy', 2, 1, 'Refunds go back to the card.',     '[0.2,0.8,0.1]')
ON CONFLICT (doc_id, doc_version, chunk_index)
  DO UPDATE SET content = EXCLUDED.content, embedding = EXCLUDED.embedding;
DELETE FROM chunks WHERE doc_id = 'refund-policy' AND doc_version < 2;
COMMIT;

// Two ranked lists of chunk ids, best first
const vectorHits = ["c4", "c9", "c2", "c7"]; // pgvector: closest in meaning
const bm25Hits = ["c7", "c4", "c5"];         // BM25: exact words, e.g. "TS-999"

// Reciprocal Rank Fusion: score(d) = sum over lists of 1 / (k + rank of d)
function rrf(lists, k = 60) {
  const score = new Map();
  for (const list of lists)
    list.forEach((id, i) => score.set(id, (score.get(id) ?? 0) + 1 / (k + i + 1)));
  return [...score].sort((a, b) => b[1] - a[1]).map(([id, s]) => id + " " + s.toFixed(4));
}
console.log(rrf([vectorHits, bm25Hits]));
// [ 'c4 0.0325', 'c7 0.0320', 'c9 0.0161', 'c2 0.0159', 'c5 0.0159' ]

// chunks[i] was shown to the model as [i + 1]
const chunks = [
  "Items can be returned within 14 days.",
  "Discounted items cannot be returned if the defect is noted on the receipt.",
];
const answer =
  "You can return an item within 14 days [1]. Delivery is free [3]. " +
  "Discounted items with a noted defect can't be returned [2]. The refund arrives in 3 days.";

function verifyCitations(answer, n) {
  const kept = [], dropped = [];
  for (const s of answer.split(/(?<=[.!?])\s+/)) {
    const refs = [...s.matchAll(/\[(\d+)\]/g)].map((m) => Number(m[1]));
    const ok = refs.length > 0 && refs.every((r) => r >= 1 && r <= n);
    (ok ? kept : dropped).push(s);
  }
  return { kept: kept.join(" "), dropped };
}
console.log(verifyCitations(answer, chunks.length));
// { kept: "You can return an item within 14 days [1]. Discounted items with a noted defect can't be returned [2].",
//   dropped: [ 'Delivery is free [3].', 'The refund arrives in 3 days.' ] }

-- 1. Keep reading the index until LIMIT is filled (pgvector 0.8.0+)
SET hnsw.iterative_scan = strict_order;

-- 2. A few large tenants: a partial index for each
CREATE INDEX ON chunks USING hnsw (embedding vector_cosine_ops) WHERE (tenant_id = 42);

-- 3. Many tenants: a partition per tenant, each with its own small index
CREATE TABLE chunks (tenant_id bigint NOT NULL, embedding vector(1024) /* ... */)
  PARTITION BY LIST (tenant_id);

ALTER TABLE chunks ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON chunks
  USING (tenant_id = current_setting('app.tenant_id', true)::bigint);

-- the app connects as role app, not as the table owner
SET ROLE app;
SELECT count(*) FROM chunks;              -- 0: no tenant set, nothing visible

BEGIN;
SET LOCAL app.tenant_id = '42';           -- for this one transaction
SELECT content FROM chunks ORDER BY embedding <=> '[1,0.1,0]' LIMIT 20;
-- Returns accepted within 14 days.
-- Refunds go back to the card.          (tenant 7's chunk is not visible)
COMMIT;

RESET ROLE;                               -- back to the table owner
SELECT count(*) FROM chunks;              -- 3: the owner bypasses RLS
